import {buildKit,profileAge,effectiveProfile,dateKey} from '../../motor/kit.mjs';
import {RISK_QUESTIONS} from '../../motor/risco.mjs';
import {publicCopy} from './public-copy.mjs';
import {loadRoutes,safeSource} from './support.mjs';
import {GATES,expandedPrecheck} from '../../motor/expansao.mjs';
import {questionsFor,validateRequirements,assessRequirements} from '../../motor/requisitos.mjs';
import {makeShareImage} from './share-image.mjs';
import {carregaPincel,gSalvar,gCheck,gCarimbo,gSublinhado} from '../../design/movimento.mjs';
import {ageLabel,searchCards,caregiverDraft,shareIsCurrent,hasAgeCoverage,riskNotices} from './journey.mjs';
import {VOCAB,QUESTIONS,RULES_VERSION,validateCatalog,assess,assessUse,requirementsFor,recommend as recommendBase,adaptationsFor,lastFeedback} from '../../motor/index.mjs';
import {load,persist,addProfile,updateProfile,feedback,favorite,setActive,removeProfile,reset,STORAGE_KEY,DEMO_TERMS_VERSION} from './state.mjs';
import {preparo,moldura,cardResumo,pergunta,progresso,aviso,vazio,recado,abas,painel,passos,lista,fonte as fonteBase,adaptacao,escolha,botao,etiquetaEstado,etiquetaTipo,avatar,nota,esc,FRASE_ACOMPANHAMENTO,FORCAS,RETORNOS,contexto,contagens,registro,plano,etiquetaFamilia,icone} from '../../design/marcacao.mjs';
const fonte=f=>f.selo_publico===null?`<div class="as-fonte"><p><a href="${esc(safeSource(f).url||'#')}" target="_blank" rel="noopener noreferrer">${esc(f.titulo)}</a></p><p>${esc(f.finalidade)}</p><p>${esc(f.nota_publica)}</p></div>`:fonteBase(safeSource(f));
const root=document.querySelector('#app');
const pauseMotion=()=>{document.documentElement.toggleAttribute('data-movimento',document.hidden);if(document.hidden)document.documentElement.setAttribute('data-movimento','pausado');};
document.addEventListener('visibilitychange',pauseMotion);pauseMotion();
root.innerHTML=carregaPincel({titulo:'Abrindo a demonstração',texto:'Carregando as ideias e ilustrações.'});
let activeDay=dateKey();
function ensureDay(){if(activeDay===dateKey())return true;activeDay=dateKey();confirmedUse=null;lastUse=null;currentMoment=null;kitSafety=null;for(const dialog of root.querySelectorAll("dialog")){dialog.close();dialog.remove();}notice("O dia mudou. Confira novamente as condições e prepare novas páginas e texto.",true);render();return false;}
window.addEventListener("focus",()=>ensureDay());
document.addEventListener("visibilitychange",()=>{if(!document.hidden)ensureDay();});
setInterval(()=>{if(!document.hidden)ensureDay();},30000);
let gesture=null, confirmedUse=null,currentMoment=null,lastUse=null,routeContent=null,kitMap=null,kitSafety=null;

let storage;try{storage=window.localStorage;}catch{storage={getItem(){throw Error()},setItem(){throw Error()},removeItem(){throw Error()}};}
let initial=load(storage),state=initial.state,storageError=initial.error,raw=initial.raw,toast='',catalog,manifest,day=0,cardTab='como',search='',filter='',undoFavorite=null,confirmationIntent=null,pendingToast=null,toastContext=null,toastTimer=null,toastPersistent=false;
const p=()=>effectiveProfile(state.profiles.find(p=>p.id===state.activeId));
const recommend=(profile,cat,options={})=>recommendBase(profile,cat,{...options,moment:currentMoment?.day===dateKey()&&currentMoment?.raw===raw&&currentMoment?.profile===profile?.id?currentMoment.moment:null});
const image=m=>({src:esc(`../ilustracoes/${m.arquivo}`),alt:m.alt});
const art=key=>image(manifest.geral[key]||manifest.padrao);
const av=profile=>image(manifest.avatares.find(a=>a.id===profile?.avatar)||manifest.avatares[0]).src;
const title=(t,sub='')=>`<div class="as-cabecalho"><h1 class="as-titulo-1">${esc(t)}</h1>${sub?`<p class="as-apoio">${esc(sub)}</p>`:''}</div>`;
const action=(text,act,opts={})=>botao(text,{...opts,extra:` data-action="${esc(act)}"`});
const link=(text,route,opts={})=>botao(text,{href:'#/'+route,...opts});
const route=()=>location.hash.startsWith('#/')?location.hash.slice(2).split('/'):['home'];
function clearNotice(){clearTimeout(toastTimer);toastTimer=null;toast='';pendingToast=null;toastContext=null;undoFavorite=null;}
function notice(text,persistent=false){const navigating=!!pendingToast;clearTimeout(toastTimer);pendingToast=null;toast=text;toastPersistent=persistent;toastContext={profileId:state.activeId,raw};if(persistent){undoFavorite=null;if(navigating)pendingToast={text,context:toastContext,persistent:true};}}
function noticeValid(n){return n&&n.profileId===state.activeId&&n.raw===raw;}
function mountNotice(){
 const message=root.querySelector('.as-recado');if(!message)return;
 const bar=root.querySelector('.as-barra-acoes');
 if(bar){bar.prepend(message);bar.style.flexWrap='wrap';message.style.flexBasis='100%';const ficha=root.querySelector('.as-ficha');if(ficha)ficha.style.paddingBottom=(bar.offsetHeight+24)+'px';}
 else {message.style.scrollMarginTop=((root.querySelector('.as-topo')?.offsetHeight||0)+16)+'px';message.scrollIntoView({block:'nearest'});}
 const current=toastContext;
 const expire=()=>{if(current!==toastContext)return;if(message.contains(document.activeElement)){toastTimer=setTimeout(expire,500);return;}message.remove();toast='';toastContext=null;undoFavorite=null;};
 clearTimeout(toastTimer);if(!toastPersistent)toastTimer=setTimeout(expire,5000);
}
function go(r,replace=false){const h='#/'+r;if(location.hash===h){render();return;}if(replace){history.replaceState(null,'',h);render();}else {pendingToast=toast?{text:toast,context:toastContext,persistent:toastPersistent}:null;toast='';location.hash=h;}}
function save(next){const error=persist(storage,next);if(error){const latest=load(storage);state=latest.state;storageError=latest.error;raw=latest.raw;notice(error,true);render();return false;}state=next;raw=JSON.stringify(next);return true;}
function fresh(){if(!ensureDay())return false;let current;try{current=storage.getItem(STORAGE_KEY)??null;}catch{return true;}if(current===raw)return true;const latest=load(storage);state=latest.state;storageError=latest.error;raw=latest.raw;undoFavorite=null;confirmationIntent=null;notice('Os dados mudaram em outra aba. Confira o perfil antes de continuar.',true);if(['delete','restore','reset'].includes(route()[0]))go('profiles',true);else render();return false;}
function cardImage(c){return image(manifest.cards[c.editorial_id??c.id]||manifest.familias[c.familia]||manifest.padrao);}
function tile(c,item,prefix='kit-item',i=1){const check=assess(c,p(),catalog);return cardResumo({card:c,familia:catalog.familias.find(f=>f.id===c.familia),imagem:cardImage(c),porque:check.compatible?(prefix==='kit-item'?`Cabe nos ${p().answers.minutes} min de hoje.${c.contexto.materiais.length?' Usa '+c.contexto.materiais.map(m=>VOCAB.resources[m].toLowerCase()).join(' e ')+', que você marcou.':' Não exige material específico.'}`:`Cabe nos ${p().answers.minutes} min de hoje.`):check.reasons[0],href:'#/card/'+c.id,modo:prefix==='kit-item'?(i===0?'destaque':''):'compacto',selo:i===0?'Comece por aqui':'',consulta:!check.compatible,motivo:check.reasons[0],salvo:p()?.favorites.includes(c.id),materiais:c.contexto.materiais.map(m=>VOCAB.resources[m]),crianca:p()?.name,prefixo:prefix});}
function entry(){return `<section class="as-entrada">${title('Um próximo passo possível.','Saiba o que fazer hoje com seu filho. E entenda por quê.')}<img class="entry-art" src="${art('entrada').src}" alt="${esc(art('entrada').alt)}">${link('Conhecer a experiência','welcome/0',{tom:'primario',bloco:true})}${link('Cadastrar uma criança fictícia','add',{bloco:true,testid:'add-child'})}<p class="as-miudo">Demonstração local, com conteúdo em revisão. Sem login ou pagamento.</p><a class="as-link" href="../index.html">Ver a proposta completa</a></section>`;}
const welcomeSteps=[['boas-vindas-acolhimento','Um começo, sem ter que resolver tudo.','Encontre uma ideia para o cotidiano, com espaço para pausar e respeitar o tempo de vocês.'],['boas-vindas-conte','Cada criança tem seu caminho.','Conte um pouco sobre a criança e os recursos da casa. Cada perfil guarda suas próprias respostas.'],['boas-vindas-kit','A ideia vem com o porquê.','Veja passos, fontes, limites e cuidados. A seleção é preliminar; você confere as condições no momento.'],['boas-vindas-ajuste','Ajuste conforme o dia acontece.','Salve, registre quando não couber ou retire uma sugestão. Usar um card não mede aprendizagem.']];
function welcome(n){const [img,t,d]=welcomeSteps[n]||welcomeSteps[0];return `<section class="as-boas-vindas"><div class="welcome-top">${link('Pular apresentação','add')}</div><img class="entry-art" src="${art(img).src}" alt="${esc(art(img).alt)}">${title(t,d)}<div class="as-pontos" aria-label="Etapa ${n+1} de 4">${[0,1,2,3].map(i=>`<span class="${i===n?'as-ponto--ativo':''}" aria-current="${i===n?'step':'false'}"></span>`).join('')}</div><div class="flow-actions">${n?link('Voltar','welcome/'+(n-1)):''}${link(n===3?'Criar primeiro perfil':'Continuar',n===3?'add':'welcome/'+(n+1),{tom:'primario',bloco:true,testid:n===3?'add-child':undefined})}</div></section>`;}

function riskHtml(){return riskNotices(p(),catalog).map(n=>aviso({tom:'avaliacao',titulo:'Antes de continuar',texto:n.text,testid:'quiz-notice-'+n.code})).join('');}
function coverage(){return `${title('Esta idade ainda não tem conteúdo.','Você não precisa responder ao quiz para descobrir isso.')}${riskHtml()}<p>O acervo não contém cards para ${esc(ageLabel(p().ageMonths))}. Não altere idade ou diagnóstico para obter uma sugestão.</p>${link('Ver cobertura e limites','help',{tom:'primario'})}${link('Editar perfil','edit')}${link('Ver crianças','profiles')}`;}
function home(){
 if(!p())return entry();const child=p(),risks=[...(child.answers.risks||[]),...(child.quizDraft?.answers.risks||[])].filter(x=>x!=='nao_sei');
 const safe=kitSafety?.day===dateKey()&&kitSafety?.profile===child.id&&kitSafety?.raw===raw?kitSafety:null;
 const intro=title('Seu kit, por momento',kitMap.texto_abertura)+riskHtml()+link('Preciso de apoio agora','apoio',{bloco:true})+link('Quer ajuda de um profissional?','help');
 if(risks.length||child.quizDraft)return intro+nota(risks.length?'Há um sinal de risco informado. Abra o apoio antes de escolher atividades.':'Conclua a revisão das respostas antes de montar o kit.')+link('Rever respostas','quiz/0');
 if(!child.answers.priority)return intro+link('Escolher meu foco','quiz/0',{tom:'primario'});
 if(!safe)return intro+`<form id="kit-safety" data-profile="${esc(child.id)}"><h2>Como está o momento agora?</h2>${[['perigo','Há perigo imediato?'],['sofrimento_intenso','Há sofrimento intenso agora?']].map(([id,t])=>`<label class="as-campo">${t}<select name="${id}" required><option value="">Escolha</option><option value="sim">Sim</option><option value="nao">Não</option><option value="nao_sei">Não sei</option></select></label>`).join('')}<p>Essas respostas não liberam nenhuma atividade. Cada ficha mantém suas confirmações.</p>${botao('Ver sugestões do kit',{tipo:'submit',tom:'primario'})}</form>`;
 const result=buildKit(kitMap,child.answers.priority,{...safe,intervalo_idade:profileAge(child),retirada:'nao',risco_positivo:'nao',rascunho:'nao'});
 const item=it=>{const c=catalog.cards.find(c=>c.id===it.id),m=kitMap.cards.find(c=>c.id===it.id);if(['nao_quero','desconforto'].includes(lastFeedback(child,c.id)?.kind))return '';return `<article class="more as-fluxo"><img src="${cardImage(c).src}" alt="" loading="lazy" style="width:100%;max-height:180px;object-fit:cover;border-radius:16px"><h3>${esc(c.titulo)}</h3><p>${esc(m.pergunta_situacao)}</p><p>${esc(m.motivo_ordenacao)}</p>${link('Ver se cabe agora','card/'+c.id)}</article>`;};
 return intro+Object.entries(result.blocos).map(([b,g])=>`<section class="more as-fluxo"><h2>${esc({momentos_dificeis:'Momentos difíceis',estimular:'Para estimular',acalmar:'Para ajudar a acalmar'}[b])}</h2>${g.visiveis.map(item).join('')||'<p>Escolha uma situação para encontrar opções deste bloco.</p>'}${g.mais.length?`<details><summary>Mais situações deste bloco</summary>${g.mais.map(item).join('')}</details>`:''}${link('Escolher outra situação','situacoes')}</section>`).join('');
}
function profiles(){return `${title('Cada criança, seu caminho.','Respostas, salvos e registros separados.')}<div class="as-criancas">${state.profiles.map(c=>`<article class="as-crianca ${c.id===state.activeId?'as-crianca--ativa':''}" data-testid="child-${esc(c.id)}">${avatar({src:av(c)})}<h2 class="as-titulo-2">${esc(c.name)}</h2><p>${ageLabel(c.ageMonths)} ${c.id===state.activeId?'· Ativa agora':''}</p>${action('Abrir perfil','switch:'+c.id,{tom:'primario'})}${c.id===state.activeId?link('Editar perfil','edit'):''}</article>`).join('')}</div>${link('Adicionar criança','add',{tom:'primario',testid:'add-child'})}`;}
function demoTermsField(){
 return `<div><p><a class="as-link" href="./termos.html" target="_blank" rel="noopener noreferrer">Ler os Termos de Uso e Privacidade da demonstração (abre em outra aba)</a></p>
 <label class="resource-option"><input type="checkbox" name="terms" value="${DEMO_TERMS_VERSION}" required data-testid="terms-accept"><span>Li e aceito os termos desta demonstração. Vou usar dados fictícios.</span></label></div>`;
}
function profileForm(edit=false){const child=edit?p():null;return `${title(edit?'O contexto pode mudar.':'Como vamos chamar a criança?',edit?'Alterações recalculam as sugestões e ficam no histórico.':'Use dados fictícios. A idade não mede habilidades.')}<form id="profile-form" data-profile="${esc(child?.id||'')}" class="as-formulario"><label class="as-campo">Apelido fictício<input name="name" required maxlength="40" value="${esc(child?.name||'')}" autocomplete="off"></label><div class="age-fields"><label class="as-campo">Mês de nascimento<select name="birth_month" required><option value="">Escolha</option>${Array.from({length:12},(_,i)=>`<option value="${i+1}" ${child?.birth?.month===i+1?'selected':''}>${i+1}</option>`).join('')}</select></label><label class="as-campo">Ano de nascimento<input type="number" name="birth_year" required min="${new Date().getFullYear()-18}" max="${new Date().getFullYear()}" value="${child?.birth?.year||''}"></label></div><p data-testid="age-now" role="status">${child?.birth?'Idade aproximada: '+ageLabel(child.ageMonths):'Informe mês e ano. Perfis antigos precisam confirmar o nascimento; nenhum mês é inventado.'}</p><label class="as-campo">O aniversário do dia de nascimento neste mês já passou?<select name="birth_passed"><option value="nao_sei">Não sei / prefiro não confirmar</option><option value="sim">Sim</option><option value="nao">Ainda não</option></select></label><p class="as-miudo">Essa confirmação vale só hoje e esclarece limites de idade. A idade é recalculada ao abrir as fichas.</p><p class="as-miudo">O acervo tem recortes próprios de 2 a 14 anos e 11 meses. Cada situação exige confirmação; idade não presume habilidade.</p><fieldset class="avatar-options as-avatares"><legend>Um símbolo para este perfil</legend>${manifest.avatares.map((a,i)=>`<label class="as-avatar-escolha"><input type="radio" name="avatar" value="${esc(a.id)}" ${(child?.avatar===a.id||!child?.avatar&&i===0)?'checked':''}>${avatar({src:image(a).src,alt:a.alt})}<span class="visually-hidden">${esc(a.id)}</span></label>`).join('')}</fieldset>${edit?'':demoTermsField()}<div class="flow-actions">${botao(edit?'Salvar alterações':'Criar perfil e responder quiz',{tipo:'submit',tom:'primario'})}${link('Cancelar',edit?'home':'profiles')}</div></form>${edit?link('Excluir esta criança','delete',{tom:'perigo'}):''}`;}
function quizQuestions(){return QUESTIONS.filter(q=>!q.showIf||(p()?.quizDraft?.answers||p()?.answers||{}).diagnoses?.includes('autismo'));}
function quiz(n){if(!hasAgeCoverage(p(),catalog))return coverage();const child=p(),draft=child.quizDraft?.answers||child.answers,qs=quizQuestions();n=Number.isInteger(n)?Math.max(0,Math.min(n,qs.length-1)):0;const q=qs[n];let options=q.options;if(['priority','queue'].includes(q.key))options=Object.fromEntries(catalog.desafios.filter(d=>!['momentos_dificeis','estimular','acalmar'].includes(d.id)&&d.estado==='ativo'&&(q.key!=='queue'||d.id!==draft.priority)).map(d=>[d.id,d.nome]));const optional=['queue','interests','diagnoses'].includes(q.key),multiple=q.type==='multi';const v=draft[q.key];const neutras=multiple?[{valor:'__none',rotulo:optional?'Prefiro não informar':'Nenhum destes'},...(!optional?[{valor:'nao_sei',rotulo:'Não sei'}]:[])]:[];return `<div class="quiz-head"><h1 class="as-titulo-3">Quiz de ${esc(child.name)}</h1>${link('Salvar e sair','home')}</div>${progresso({atual:n+1,total:qs.length})}<form id="quiz-form" data-profile="${esc(child.id)}" data-step="${n}">${pergunta({visual:!['risks','diagnoses','support'].includes(q.key),chave:q.key,titulo:q.label,dica:q.key==='diagnoses'?'Opcional. Você pode seguir sem informar. Não inferimos diagnóstico.':q.key==='support'?'Somente o que está informado em laudo. Não determina o kit.':q.key==='queue'?'Escolha até dois. O foco só muda quando você decidir.':q.key==='interests'?'Até três interesses. Eles apenas ordenam sugestões.':multiple?'Escolha os conhecidos, nenhum ou não sei.':'Escolha o que melhor descreve este momento.',tipo:q.type,opcoes:Object.entries(options).map(([valor,rotulo])=>({valor,rotulo,arte:['priority','queue'].includes(q.key)?image(manifest.familias[valor]||manifest.padrao).src:undefined,numero:q.key==='minutes'?rotulo:undefined,icone:['priority','queue'].includes(q.key)?valor:'',familia:['priority','queue'].includes(q.key)?valor:''})),neutras,valor:Array.isArray(v)&&!v.length?['__none']:q.key==='minutes'?(v===null?'nao_sei':String(v??'')):v,obrigatoria:q.required})}<div id="quiz-risk-notices" role="alert" aria-atomic="true">${riskHtml()}</div><p id="form-error" role="alert"></p><div class="as-quiz-acoes">${n?link('Voltar','quiz/'+(n-1)):link('Voltar','home')}${botao(n===qs.length-1?'Ver meu kit':'Continuar',{tipo:'submit',tom:'primario',testid:'quiz-next'})}</div></form>`;}
function detail(id){const c=catalog.cards.find(c=>c.id===id);if(c?.regra_integracao)return expandedDetail(c);if(!c)return `${title('Conteúdo indisponível.','Este card saiu do catálogo. Seu registro permanece no histórico.')}${link('Ver salvos','saved')}`;const child=p(),check=assess(c,child,catalog),im=cardImage(c),f=lastFeedback(child,c.id),withdrawn=['desconforto','nao_quero'].includes(f?.kind);const why=c.por_que;const panels={
 como:`${preparo({itens:[{icone:'materiais',texto:c.contexto.materiais_detalhados||'Confira os materiais dos passos.'},...(c.contexto.requisitos_nao_inferiveis||[]).map(texto=>({icone:'certo',texto})),{icone:'relogio',texto:c.contexto.nota_tempo||'Tempo aproximado, sem obrigação de completar.'}],limites:[c.editorial?.limite_do_quiz].filter(Boolean)})}<h2 class="as-titulo-2">Como começar</h2>${passos(c.passos)}`,
 porque:`<h2 class="as-titulo-2">${esc(why.principio)}</h2><p>${esc(why.explicacao||'')}</p><h3>Por que apareceu para ${esc(child.name)}?</h3>${lista(check.trace.filter(t=>t.passed&&['age','understanding','requirement','material','time'].includes(t.id)).map(t=>t.text))}<h3>Limites</h3><p>${esc(why.limites)}</p><p>Força da evidência: ${esc(FORCAS[why.forca_da_evidencia])}</p><p>${esc(why.justificativa_da_forca||'')}</p><div data-testid="card-sources">${why.fontes.map(fonte).join('')}</div><p class="as-miudo">Autoria: ${esc(c.revisao.autor)} · Revisão: ${esc(c.revisao.revisor||'sem revisão humana')} · Versão ${esc(c.versao)}</p>`,
 adaptar:`<h2 class="as-titulo-2">Variações para avaliar</h2>${adaptationsFor(c,child).map(adaptacao).join('')||'<p>Nenhuma adaptação corresponde às respostas atuais. Não force uma variação.</p>'}`,
 cuidados:`<h2 class="as-titulo-2">O que evitar</h2>${lista(c.evite,{tom:'evite'})}<h3>Se não der certo</h3>${lista(c.se_nao_der_certo)}<h3>Quando buscar ajuda</h3>${lista(c.procure_ajuda_se)}`};
 return `<a class="as-voltar" href="#/home">${icone("seta-esquerda")}Voltar ao kit</a><article class="as-ficha" data-familia="${esc(c.familia)}"><div class="as-ficha-arte"><img class="detail-art" src="${im.src}" alt="${esc(im.alt)}"></div><div class="status-line">${etiquetaFamilia(catalog.familias.find(f=>f.id===c.familia))}${etiquetaTipo(c.tipo)}${etiquetaEstado(c.status)}</div>${title(c.titulo,'Card de '+child.name)}${!check.compatible?aviso({tom:'atencao',titulo:'Somente consulta',texto:check.reasons.join(' ')}):''}${f?.kind==='desconforto'?aviso({tom:'avaliacao',texto:catalog.orientacoes.desconforto,testid:'notice-desconforto'}):''}${abas({ativa:cardTab,itens:[['como','Como fazer','passos'],['porque','Por quê','porque'],['adaptar','Adaptar','adaptar'],['cuidados','Cuidados','cuidados']].map(([id,rotulo,icone])=>({id,rotulo,icone}))})}${painel(cardTab,panels[cardTab])}${check.compatible?action('Preparar para cuidador','share:'+id):''}${c.observacao?`<p><strong>O que observar:</strong> ${esc(c.observacao)}</p>`:''}${nota(FRASE_ACOMPANHAMENTO)}<div class="as-barra-acoes">${gSalvar({salvo:child.favorites.includes(id),agora:gesture?.kind==='favorite'&&gesture?.profile===child.id&&gesture?.card===id,testid:'card-save'}).replace('<button ',`<button data-action="favorite:${esc(id)}" `)}${check.compatible?action('Como coube hoje?','return:'+id,{tom:'primario'}):withdrawn?action('Rever retirada','restore:'+id):''}</div></article>`;}
function saved(){const child=p();return `${title('Salvos de '+child.name,'O que vocês querem reencontrar.')}<div class="as-grade">${child.favorites.map(id=>{const c=catalog.cards.find(c=>c.id===id);return c?tile(c,null,'saved-item'):`<p>Card ${esc(id)} indisponível no catálogo atual. Registro preservado.</p>`;}).join('')||vazio({arte:art('vazio').src,titulo:'Sua caixa ainda está vazia.',texto:'Salve uma ideia para encontrar aqui depois.',acoesHtml:link('Explorar sugestões','explore')})}</div>${link('Ver nosso caminho','path',{testid:'path-open'})}`;}
function explore(){const result=searchCards(catalog.cards,search,filter),cards=[...result.cards].sort((a,b)=>Number(assess(b,p(),catalog).compatible)-Number(assess(a,p(),catalog).compatible));return `${title('Uma possibilidade de cada vez.','Confira o que combina com '+p().name+'.')}<form id="search-form" class="as-busca"><label class="as-so-leitor" for="search-input">Buscar no acervo</label><input id="search-input" name="search" value="${esc(search)}" type="search" placeholder="Brincar, birra, sair de casa…">${botao('Buscar',{tipo:'submit'})}</form><div class="as-filtros as-filtros--trilho" aria-label="Filtrar por desafio">${action('Todos','filter:',{pressionado:!filter})}${catalog.desafios.map(d=>action(d.nome,'filter:'+d.id,{pressionado:filter===d.id,testid:'search-theme-'+d.id})).join('')}</div>${result.limited?nota('Resultados relacionados não substituem orientação específica para crises, conflitos ou distúrbios do sono.'):''}<div class="as-grade">${cards.map(c=>tile(c,null,'explore-item')).join('')||vazio({arte:art('vazio').src,titulo:'Ainda não temos essa orientação.',texto:'O acervo não cobre toda situação. Você pode consultar os desafios disponíveis, sem forçar uma sugestão.'})}</div><section class="more as-fluxo"><h2 class="as-titulo-2">Limites do acervo</h2><p>${esc(catalog.limits.replace('24–59 meses','2 a 4 anos e 11 meses').replace('108 meses','9 anos').replace('Nenhum conteúdo humano aprovado.','Nenhum card foi aprovado por um profissional.'))}</p>${catalog.expansion.map(d=>`<p>${esc(d.nome)} · ${d.estado==='fora_do_escopo'?'Fora do escopo':'Em preparação'}</p>`).join('')}</section>`;}
function path(){const c=p(),events=[...new Map(c.feedback.map(f=>[f.id,f])).values()];const tried=new Set(events.filter(f=>f.kind==='usamos').map(f=>f.cardId));return `${title('O caminho de '+c.name,'Um registro das suas tentativas, sem medir o desenvolvimento da criança.')}<div class="as-segmento">${link('Guardados','saved')}${link('Caminho','path',{pressionado:true})}</div><div data-testid="path-summary">${contagens([[tried.size,'ideias tentadas'],[c.favorites.length,'guardadas'],[new Set(events.filter(f=>['adaptar','nao_coube'].includes(f.kind)).map(f=>f.cardId)).size,'ideias para ajustar']])}</div>${events.length?registro({titulo:'O que vocês registraram',testid:'path-log',linhas:events.slice().reverse().map(f=>({rotulo:RETORNOS[f.kind]?.rotulo||'Registro',data:new Date(f.at).toLocaleDateString('pt-BR'),titulo:catalog.cards.find(x=>x.id===f.cardId)?.titulo||'Card fora do catálogo',nota:f.kind==='desconforto'?'Sugestão retirada. Avise quem recebeu uma cópia externa.':''}))}):vazio({arte:art('vazio').src,titulo:'Cada tentativa tem seu lugar.',texto:'Quando você registrar como uma ideia coube, ela aparece aqui.'})}<details class="more"><summary>Contexto que mudou</summary>${c.history.slice().reverse().map(h=>`<p>${h.kind==='criado'?'Perfil criado':h.changed.map(k=>({ageMonths:'Idade atualizada',name:'Apelido atualizado',avatar:'Símbolo atualizado',minutes:'Tempo disponível atualizado',resources:'Materiais atualizados',priority:'Foco atualizado'})[k]||QUESTIONS.find(q=>q.key===k)?.label||'Respostas atualizadas').join(' · ')}</p>`).join('')}</details>`;}
function contextForm(){const c=p();if(!hasAgeCoverage(c,catalog))return coverage();if(c.quizDraft)return `${title('Conclua a revisão em andamento.','Depois você pode mudar só o tempo ou os materiais.')} ${link('Retomar quiz','quiz/'+c.quizDraft.step,{tom:'primario'})}`;return `${title('O que cabe hoje?','Ajuste o contexto de '+c.name+'. O kit será conferido de novo.')}<form id="context-form" data-profile="${esc(c.id)}"><label class="as-campo">Tempo disponível<select name="minutes">${[2,5,10,20].map(n=>`<option value="${n}" ${c.answers.minutes===n?'selected':''}>${n} minutos</option>`).join('')}<option value="unknown" ${c.answers.minutes==null?'selected':''}>Não sei</option></select></label><fieldset class="as-pergunta"><legend>Materiais que estão disponíveis</legend>${Object.entries(VOCAB.resources).filter(([k])=>k!=='nao_sei').map(([k,v])=>`<label class="resource-option"><input type="checkbox" name="resources" value="${k}" ${(c.answers.resources||[]).includes(k)?'checked':''}>${esc(v)}</label>`).join('')}<label class="resource-option"><input name="unknown" type="checkbox" ${c.answers.resources?.includes('nao_sei')?'checked':''}>Não sei quais materiais estão disponíveis</label></fieldset>${botao('Atualizar kit',{tipo:'submit',tom:'primario',testid:'context-save'})}</form>${link('Rever todas as respostas','quiz/0')}`;}
