function plans(){return `${title('Um apoio que cabe na rotina.','Estudo de planos. Sem compra, anúncio ou cobrança nesta demonstração.')}${plano({nome:'Gratuito',atual:true,resumo:'Primeira orientação útil e completa.',itensHtml:lista(['Passos, cuidados e fontes juntos','Adaptações necessárias incluídas','Perfis e salvos disponíveis na demonstração']),acoesHtml:link('Continuar grátis','home',{tom:'primario',testid:'plan-keep-free'})})}${plano({nome:'Mais organização',resumo:'Hipótese para uma versão futura. Preço e limites ainda não definidos.',itensHtml:lista(['Organização da rotina','Ausência de anúncios na versão futura']),acoesHtml:'<p>Nenhuma contratação disponível.</p>'})}<h2 class="as-titulo-2">Nunca dependem de plano</h2><p>Cuidados, fontes, adaptações necessárias e orientações de segurança. Falta de conteúdo e desconforto não são convite para pagar.</p>`;}

